    "statement": "Evidence for using unpalatable buffer crops to prevent primates from entering agricultural areas has not been found.",
    "citations": [
      "1438"
    ]
  },
  {
    "statement": "No studies have directly and quantitatively tested the effects of using unpalatable buffer crops on primate populations.",
    "citations": [
      "1438"
    ]
  },
  {
    "statement": "A laboratory study on genetically modified maize expressing Bacillus thuringiensis kurstaki (Btk) toxin reported that the maize's pollen did not reduce survival or growth of eastern tiger swallowtail caterpillars compared to non-genetically modified maize.",
    "citations": [
      "3895"
    ]
  },
  {
    "statement": "A laboratory study on genetically modified maize expressing Bacillus thuringiensis kurstaki (Btk) toxin reported that the maize's pollen did not reduce survival or growth of spicebush swallowtail caterpillars compared to non-genetically modified maize.",
    "citations": [
      "3895"
    ]
  },
  {
    "statement": "No studies on the effects of genetically modified maize expressing Bacillus thuringiensis kurstaki (Btk) toxin on primates were reported.",
    "citations": [
      "3895"
    ]
  }
